Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // Load the Rust core (libcc_ffi) before the first screen.
  await initRustCore();
  const core = RustCoreApi();
  await configureCodecDir(core);
  final settings = await AppSettings.load(
    core: core,
    // Development only: COMETCAST_SERVER=host:port overrides the saved server.
    envServer: _env('COMETCAST_SERVER'),
    // Development only: bind WebRTC to one local address, e.g. COMETCAST_UDP_BIND=127.0.0.1:0.
    udpBind: _env('COMETCAST_UDP_BIND'),
    // Development only: share another X11 display, e.g. COMETCAST_CAPTURE_DISPLAY=:99.
    captureDisplay: _env('COMETCAST_CAPTURE_DISPLAY'),
  );
  final android = await _androidSetup(core);
  // Links, the install referrer and the QR scanner exist on phones and tablets only.
  final mobile = Platform.isAndroid || Platform.isIOS;
  final handler = LinkHandler(core: core, settings: settings);
  final appLinks = mobile ? ChannelAppLinks() : null;
  // The referrer exists on the first launch only: no referrer read yet = first launch.
  final firstLaunch =
      mobile &&
      !(await (settings.store?.loadReferrerRead() ?? Future.value(true)));
  final launch = mobile
      ? await resolveLaunch(
          links: appLinks!,
          handler: handler,
          store: settings.store,
        )
      : null;
  final scanner = mobile ? const ChannelQrScanner() : null;
  final canScan = scanner != null && await scanner.isAvailable();
  runApp(
    CometCastApp(
      core: core,
      settings: settings,
      // Used only when the Rust core lists the Android projection (Android builds).
      androidCapture: Platform.isAndroid ? const ChannelAndroidCapture() : null,
      // Used only when the Rust core lists the iOS broadcast (iOS builds).
      iosBroadcast: Platform.isIOS ? const ChannelIosBroadcast() : null,
      tv: android.tv,
      androidPlatform: android.platform,
      // iOS: VideoToolbox through the same channel protocol as the Android MediaCodec bridge
      // (ios/Runner/Video/VideoBridge.swift). There is no software fallback on iOS.
      videoDecoder: Platform.isIOS
          ? const ChannelAndroidVideoDecoder()
          : android.videoDecoder,
      hardwareDecoderOnly: Platform.isIOS,
      deviceName: android.deviceName,
      // Windows only: the DLL is loaded when the Miracast screen is first used.
      miracast: miracastSupportedHere() ? FfiMiracastCore() : null,
      launch: launch,
      linkStream: appLinks?.links,
      firstLaunch: firstLaunch && launch is LinkNothing,
      links: handler,
      scanQr: canScan ? scanner.scan : null,
    ),
  );
}

/// What this device is (Android only): television or not, the model name, the workers, and
/// whether received video goes through the hardware decoder.
///
/// `--dart-define=COMETCAST_VIDEO=auto|hardware|software` (default `auto`): `auto` uses the
/// device's own decoder (MediaCodec into a texture) on a television and the software decoder of
/// the core elsewhere; the other two force one path, for measuring both on the same device
/// (docs/android-device-test-plan.md). UNCERTAIN: neither path was run on a device.
Future<
  ({
    bool tv,
    AndroidPlatform? platform,
    AndroidVideoDecoder? videoDecoder,
    String? deviceName,
  })
>
_androidSetup(CoreApi core) async {
  if (!Platform.isAndroid) {
    return (tv: false, platform: null, videoDecoder: null, deviceName: null);
  }
  const platform = ChannelAndroidPlatform();
  var tv = false;
  String? name;
  try {
    tv = await platform.isTelevision();
    final info = await platform.deviceInfo();
    // One line for `adb logcat -s flutter`: what a device test ran on.
    debugPrint('cometcast: device $info');
    final model = info['model'];
    if (model is String && model.trim().isNotEmpty) name = model.trim();
    await configureAndroidWorkers(core, platform);
    debugPrint(
      'cometcast: docs worker ${core.docsWorkerPath()}, '
      'office worker ${core.officeWorkerPath()}',
    );
  } catch (e) {
    debugPrint('cometcast: Android setup failed: $e');
  }
  const mode = String.fromEnvironment('COMETCAST_VIDEO', defaultValue: 'auto');
  final hardware = mode == 'hardware' || (mode == 'auto' && tv);
  return (
    tv: tv,
    platform: platform,
    videoDecoder: hardware ? const ChannelAndroidVideoDecoder() : null,
    deviceName: name,
  );
}

String? _env(String name) {
  final v = Platform.environment[name];
  return (v == null || v.isEmpty) ? null : v;
}

/// Root widget (like App.vue). Pass [locale] to force a language (used by tests).
class CometCastApp extends StatelessWidget {
  CometCastApp({
    super.key,
    this.locale,
    required this.core,
    AppSettings? settings,
    this.androidCapture,
    this.iosBroadcast,
    this.hardwareDecoderOnly = false,
    this.pickFile = pickImageOrPdf,
    this.openUrl = launchInBrowser,
    this.tv = false,
    this.androidPlatform,
    this.videoDecoder,
    this.deviceName,
    this.miracast,
    this.displayStore = const PrefsDisplayStore(),
    this.wakeLock,
    this.forceDisplayCapable,
    this.initialCode,
    this.launch,
    this.linkStream,
    this.firstLaunch = false,
    this.links,
    this.scanQr,
    this.canOpenLinks,
  }) : settings = settings ?? AppSettings.fromDefaults(core.serverDefaults());

  /// What the display remembers (a memory store in tests).
  final DisplayStore displayStore;

  /// The wake lock (a fake in tests).
  final WakeLockControl? wakeLock;

  /// Tests: treat this device as a tablet or computer (true) or a phone (false).
  final bool? forceDisplayCapable;

  /// A code from a link (tests).
  final String? initialCode;

  /// What started the app: a link or the install referrer (null on computers and in most tests).
  final LinkOutcome? launch;
  final Stream<String>? linkStream;
  final bool firstLaunch;

  /// Turns scanned codes and links into chips and relay confirmations.
  final LinkHandler? links;

  /// The system QR scanner; null where none exists (computers): no scan button.
  final ScanQr? scanQr;

  /// Can the system open web links? Null = ask the system (tests answer directly).
  final CanOpenLinks? canOpenLinks;

  final Locale? locale;

  /// A television (Android TV / Google TV): receiver only, big room code, remote control.
  final bool tv;

  /// Android hooks such as keep-screen-on (a fake in tests); null elsewhere.
  final AndroidPlatform? androidPlatform;

  /// The device's own video decoder, or null for the software decoder.
  final AndroidVideoDecoder? videoDecoder;

  /// The name this device announces itself with, or null for the host name.
  final String? deviceName;

  /// The Android screen capture (a fake in tests); null on other platforms.
  final AndroidCapture? androidCapture;

  /// The iOS broadcast hand-over (a fake in tests); null on other platforms.
  final IosBroadcast? iosBroadcast;

  /// No software video decoder exists (iOS): see [DeviceProfile.hardwareDecoderOnly].
  final bool hardwareDecoderOnly;

  /// The Windows Miracast receiver (a fake in tests); null on other platforms, which hides
  /// the "Receive via Miracast (Windows)" row.
  final MiracastCore? miracast;

  /// The Rust core (or a fake in tests).
  final CoreApi core;

  /// The file dialog (a fake in tests).
  final PickFile pickFile;

  /// Opens a link after the person chose "Open" (a fake in tests).
  final UrlOpener openUrl;

  /// Settings shared by the screens (server address).
  final AppSettings settings;

  @override
  Widget build(BuildContext context) {
    return DeviceProfile(
      tv: tv,
      platform: androidPlatform,
      videoDecoder: videoDecoder,
      hardwareDecoderOnly: hardwareDecoderOnly,
      deviceName: deviceName,
      child: _app(),
    );
  }

  Widget _app() {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      // onGenerateTitle is used because the title needs translations.
      onGenerateTitle: (context) => AppLocalizations.of(context).appTitle,
      locale: locale, // null = follow the system language
      localizationsDelegates: const [
        AppLocalizations.delegate,
        GlobalMaterialLocalizations.delegate,
        GlobalWidgetsLocalizations.delegate,
        GlobalCupertinoLocalizations.delegate,
      ],
      supportedLocales: const [Locale('en'), Locale('de')],
      // Use the system language if supported, otherwise English.
      localeResolutionCallback: (deviceLocale, supported) {
        for (final l in supported) {
          if (l.languageCode == deviceLocale?.languageCode) return l;
        }
        return const Locale('en');
      },
      // The presenter pages follow the system; the display brings its own theme
      // (lib/src/design/tokens.dart).
      theme: presenterTheme(Brightness.light),
      darkTheme: presenterTheme(Brightness.dark),
      themeMode: ThemeMode.system,
      home: AppShell(
        core: core,
        settings: settings,
        androidCapture: androidCapture,
        iosBroadcast: iosBroadcast,
        pickFile: pickFile,
        openUrl: openUrl,
        miracast: miracast,
        store: displayStore,
        wakeLock: wakeLock,
        forceDisplayCapable: forceDisplayCapable,
        initialCode: initialCode,
        launch: launch,
        linkStream: linkStream,
        firstLaunch: firstLaunch,
        links: links,
        scanQr: scanQr,
        canOpenLinks: canOpenLinks,
      ),
    );
  }
}
